<template>
	<view class="chat-page" :class="{ 'keyboard-open': keyboardHeight > 0 }">
		<view class="chat-header" :style="{ paddingTop: headerTopPadding + 'px' }">
			<view class="header-inner" :style="{ height: headerInnerHeight + 'px', paddingRight: headerRightPadding + 'px' }">
				<view class="nav-btn back-btn" @click="goBack"></view>
				<view class="peer-head" @click="goUserHome">
				<view class="peer-avatar-wrap">
					<image class="peer-avatar" :src="peer.avatar" mode="aspectFill" />
					<view v-if="peer.online" class="online-dot"></view>
					</view>
					<view class="peer-copy">
						<view class="peer-name-row">
							<VipName class="peer-name" :name="peer.name" :is-member="peer.isMember" />
							<text v-if="peer.gender || peer.age" class="peer-age-pill">{{ peer.gender }} {{ peer.age }}</text>
							<text v-if="peer.match" class="match-chip">同频</text>
						</view>
						<text class="peer-state">{{ peer.state }}</text>
					</view>
				</view>
				<view class="header-more" @click.stop="showMoreActions">•••</view>
			</view>
		</view>
		<view
			v-if="subscriptionBannerVisible"
			class="reply-reminder-banner"
			:class="{ loading: subscriptionRequesting }"
			:style="{ top: headerHeight + 'px' }"
			hover-class="reply-reminder-banner-hover"
			hover-stay-time="80"
			@click="enableReplyReminder"
		>
			<view class="reply-reminder-banner-icon-wrap">
				<view class="reply-reminder-banner-icon">
					<view class="reply-reminder-banner-dome"></view>
					<view class="reply-reminder-banner-base"></view>
					<view class="reply-reminder-banner-clapper"></view>
				</view>
			</view>
			<view class="reply-reminder-banner-content">
				<text class="reply-reminder-banner-title">离线回复提醒</text>
			</view>
			<view class="reply-reminder-banner-action" @click.stop="enableReplyReminder">开启</view>
		</view>

		<scroll-view
			class="chat-scroll"
			scroll-y
			enhanced
			:show-scrollbar="false"
			:scroll-into-view="scrollIntoView"
			:style="chatScrollStyle"
			upper-threshold="80"
			@scroll="handleScroll"
			@scrolltoupper="loadOlderMessages"
			@scrolltolower="handleScrollToLower"
			@click="handlePageTap"
		>
			<view class="chat-body">
				<view v-if="loadingOlder" class="history-tip">正在加载更早的消息</view>
				<view v-else-if="!hasMore && messages.length" class="history-tip muted">已经到最开始了</view>

				<view v-if="loading && !messages.length" class="chat-loading">
					<view class="loading-dot"></view>
					<text>正在进入会话</text>
				</view>

				<view v-else-if="!messages.length" class="chat-empty">
					<image class="empty-avatar" :src="peer.avatar" mode="aspectFill" />
					<text class="empty-title">和 {{ peer.name }} 打个招呼</text>
					<text class="empty-desc">一句轻一点的开场，会让聊天自然很多</text>
				</view>

				<block v-for="item in timelineItems" :key="item.key">
					<view v-if="item.kind === 'time'" class="time-tip">{{ item.label }}</view>
					<view v-else-if="item.kind === 'system'" class="system-tip">{{ item.label }}</view>
					<view v-else-if="item.kind === 'membership-gift'" class="membership-gift-message">
						<image src="/static/img/VIP-icon.png" mode="aspectFit" />
						<text>{{ item.label }}</text>
					</view>
					<view v-else-if="item.kind === 'gift'" class="present-message-row" :class="{ mine: item.message.mine }">
						<image class="present-message-avatar" :src="item.message.mine ? myAvatar : peer.avatar" mode="aspectFill" />
						<view class="present-message" @click.stop="playPresent(item.message.gift)">
							<image class="present-message-image" :src="item.message.gift.staticImageUrl" mode="aspectFit" />
							<view class="present-message-copy">
								<text class="present-message-name">{{ item.message.gift.name }}</text>
								<text class="present-message-charm">{{ item.message.mine ? '对方魅力' : '你的魅力' }} +{{ item.message.gift.charmValue }}</text>
								<text v-if="item.message.gift.giftBonusDiamonds" class="present-message-bonus">{{ item.message.mine ? '对方获得彩蛋' : '你获得彩蛋' }} +{{ item.message.gift.giftBonusDiamonds }} 钻石</text>
							</view>
						</view>
					</view>
					<view
						v-else
						:id="`msg-${item.message.id}`"
						class="message-row"
						:class="{ mine: item.message.mine, failed: item.message.failed, sending: item.message.pending }"
					>
						<image class="avatar" :src="item.message.mine ? myAvatar : peer.avatar" mode="aspectFill" />
						<view class="bubble-wrap">
							<text v-if="item.message.tag" class="message-tag">{{ item.message.tag }}</text>
							<view
								class="bubble"
								:class="{
									'image-bubble': item.message.messageType === 'image',
									'flash-bubble': item.message.messageType === 'flash_image',
									'audio-bubble': item.message.messageType === 'audio',
									playing: playingAudioId === item.message.id && audioPlaybackStarted,
									loading: playingAudioId === item.message.id && !audioPlaybackStarted
								}"
								:style="item.message.messageType === 'audio' ? getAudioBubbleStyle(item.message) : ''"
								@click.stop="handleBubbleClick(item.message)"
							>
								<image
									v-if="item.message.messageType === 'image'"
									class="message-image"
									:src="item.message.imageUrl"
									mode="aspectFill"
									@click.stop="previewImage(item.message)"
								/>
				<view
					v-else-if="item.message.messageType === 'flash_image'"
					class="flash-message"
					:class="{ viewed: item.message.flashOpenedAt }"
				>
					<view class="flash-message-icon">
						<image src="/static/img/shantu.png" mode="aspectFit" />
					</view>
					<view class="flash-message-copy">
						<view class="flash-message-head">
							<text class="flash-message-title">闪图</text>
							<text class="flash-message-badge">3s</text>
						</view>
						<view class="flash-message-status">
							<view class="flash-message-dot"></view>
							<text class="flash-message-state">{{ item.message.mine ? (item.message.flashOpenedAt ? '对方已查看' : '等待查看') : (item.message.flashOpenedAt ? '已查看' : '点击查看') }}</text>
							<text v-if="!item.message.mine && !item.message.flashOpenedAt" class="flash-message-arrow">›</text>
						</view>
					</view>
				</view>
								<view v-else-if="item.message.messageType === 'audio'" class="audio-message">
									<view class="audio-signal">
										<view class="audio-signal-dot"></view>
										<view class="audio-signal-wave wave-one"></view>
										<view class="audio-signal-wave wave-two"></view>
										<view class="audio-signal-wave wave-three"></view>
									</view>
									<text class="audio-duration">{{ formatAudioDuration(item.message.audioDuration) }}</text>
								</view>
								<text v-else>{{ item.message.content }}</text>
							</view>
							<text
								v-if="item.message.status"
								class="message-status"
								:class="{ failed: item.message.failed, sending: item.message.pending }"
								@click.stop="retryMessage(item.message)"
							>
								{{ item.message.status }}
							</text>
						</view>
					</view>
				</block>

				<view id="chat-bottom" class="bottom-spacer" :style="{ height: bottomSpacerHeight }"></view>
			</view>
		</scroll-view>

		<view v-if="pendingNewCount" class="new-message-pill" :style="newMessagePillStyle" @click="jumpToLatest">
			{{ pendingNewCount }} 条新消息
		</view>

		<view v-if="!showToolPanel && !showEmojiPanel && !voiceMode" class="quick-replies" :style="quickRepliesStyle">
			<view v-for="item in quickReplies" :key="item" class="quick-reply" @click="useQuickReply(item)">{{ item }}</view>
		</view>

		<view class="composer" :style="composerStyle" @click.stop>
			<view class="tool-btn" @click="toggleToolPanel"></view>
			<view
				v-if="voiceMode"
				class="voice-record-btn"
				:class="{ recording, canceling: recordingCancelPending }"
				@touchstart.stop.prevent="startRecording"
				@touchmove.stop.prevent="handleRecordingTouchMove"
				@touchend.stop.prevent="finishRecording"
				@touchcancel.stop.prevent="cancelRecording"
			>
				{{ recording ? (recordingCancelPending ? '松开取消' : `松开发送 ${recordingDuration}s`) : '按住说话' }}
			</view>
			<input
				v-else
				v-model="draft"
				class="input"
				placeholder="写一句话"
				placeholder-class="placeholder"
				confirm-type="send"
				:confirm-hold="true"
				:adjust-position="false"
				:hold-keyboard="true"
				@focus="closePanels"
				@input="handleDraftInput"
				@confirm="sendFromComposer"
				@keyboardheightchange="handleKeyboardHeightChange"
			/>
			<view v-if="!voiceMode" class="emoji-btn" :class="{ active: showEmojiPanel }" @click="toggleEmojiPanel">
				<image class="emoji-icon" src="/static/img/emoji-icon.png" mode="aspectFit" />
			</view>
			<view class="voice-btn" :class="{ active: voiceMode }" @tap.stop="toggleVoiceMode">
				<image class="voice-icon" src="/static/img/yuyin.png" mode="aspectFit" />
			</view>
			<view
				v-if="!voiceMode"
				class="send-btn"
				:class="{ disabled: !draft.trim() }"
				@touchstart.stop="handleSendTouchStart"
				@tap.stop="sendFromComposer"
			>
				发送
			</view>
		</view>

		<view v-if="recording" class="recording-float" :class="{ canceling: recordingCancelPending }">
			<view class="recording-pulse"></view>
			<text>{{ recordingCancelPending ? '松开手指，取消发送' : `正在录音 ${recordingDuration}s · 上滑取消` }}</text>
		</view>

		<view v-if="showToolPanel" class="tool-panel" :style="toolPanelStyle" @click.stop>
			<view v-for="item in tools" :key="item.label" class="tool-entry" @click="handleToolClick(item)">
				<view class="tool-icon">
					<image class="tool-icon-image" :class="item.iconClass" :src="item.icon" mode="aspectFit" />
				</view>
				<text>{{ item.label }}</text>
			</view>
		</view>

		<view v-if="showEmojiPanel" class="emoji-panel" :style="toolPanelStyle" @click.stop>
			<scroll-view class="emoji-scroll" scroll-y :show-scrollbar="false">
				<view class="emoji-grid">
					<view v-for="emoji in emojis" :key="emoji" class="emoji-item" @click="sendEmoji(emoji)">{{ emoji }}</view>
				</view>
			</scroll-view>
		</view>

		<view v-if="vipPromptVisible" class="vip-prompt-mask" @touchmove.stop.prevent @click.stop>
			<view class="vip-prompt" @click.stop>
				<view class="vip-mark">VIP</view>
				<text class="vip-prompt-title">开启无限畅聊</text>
				<text class="vip-prompt-desc">当前钻石不足。开通会员后，私信聊天不再消耗钻石。</text>
				<view class="vip-prompt-actions">
					<view class="vip-prompt-btn secondary" @click="closeVipPrompt">暂不开通</view>
					<view class="vip-prompt-btn primary" @click="goMembership">开通 VIP</view>
				</view>
			</view>
		</view>

		<view v-if="giftPromptVisible" class="gift-prompt-mask" @touchmove.stop.prevent @click.stop>
			<view class="gift-prompt" @click.stop>
				<view class="gift-prompt-head">
					<image src="/static/img/VIP-icon.png" mode="aspectFit" />
					<view class="gift-prompt-copy">
						<text class="gift-prompt-title">赠送会员</text>
						<text class="gift-prompt-target">赠送给 {{ peer.name }}</text>
					</view>
					<view class="gift-close" @click="closeGiftPrompt">×</view>
				</view>
				<view v-if="giftPlansLoading" class="gift-plans-loading">正在加载套餐</view>
				<view v-else class="gift-plan-list">
					<view
						v-for="plan in giftPlans"
						:key="plan.type"
						class="gift-plan"
						:class="{ selected: selectedGiftPlanType === plan.type }"
						@click="selectGiftPlan(plan)"
					>
						<view class="gift-plan-main">
							<text class="gift-plan-name">{{ plan.name }}</text>
							<text class="gift-plan-days">会员权益 {{ plan.days }} 天</text>
						</view>
						<text class="gift-plan-price">¥{{ formatGiftPrice(plan.price) }}</text>
						<view class="gift-plan-check"></view>
					</view>
				</view>
				<view class="gift-notice">支付成功后，会员时长将直接加入对方账户</view>
				<view class="gift-pay-button" :class="{ disabled: giftPaying || !selectedGiftPlan }" @click="confirmGiftMembership">
					<text>{{ giftPaying ? '正在确认...' : '确认赠送' }}</text>
					<text v-if="!giftPaying && selectedGiftPlan"> · ¥{{ formatGiftPrice(selectedGiftPlan.price) }}</text>
				</view>
			</view>
		</view>

		<view v-if="presentPanelVisible" class="present-panel-mask" @touchmove.stop.prevent @click.stop>
			<view class="present-panel" @click.stop>
				<view class="present-head">
					<view class="present-head-copy">
						<text class="present-title">送给 {{ peer.name }}</text>
						<view class="present-balance"><image src="/static/img/zuanshi.png" mode="aspectFit" /><text>余额 {{ presentDiamondBalance }}</text></view>
					</view>
					<view class="gift-close" @click="closePresentPanel">×</view>
				</view>
				<view v-if="presentLoading" class="gift-plans-loading">正在加载礼物</view>
				<scroll-view v-else class="present-scroll" scroll-y>
					<view class="present-grid">
						<view v-for="gift in presents" :key="gift.id" class="present-item" :class="{ selected: selectedPresent && selectedPresent.id === gift.id, locked: gift.memberOnly && !presentIsMember }" @click="selectPresent(gift)">
							<view v-if="gift.memberOnly || gift.hasDiamondBonus" class="present-flags">
								<text v-if="gift.memberOnly" class="present-vip">VIP</text>
								<text v-if="gift.hasDiamondBonus" class="present-bonus">彩蛋</text>
							</view>
							<view v-if="selectedPresent && selectedPresent.id === gift.id" class="present-selected-mark">✓</view>
							<view class="present-image-wrap"><image class="present-image" :src="gift.staticImageUrl" mode="aspectFit" /></view>
							<text class="present-name">{{ gift.name }}</text>
							<view class="present-meta">
								<view class="present-price"><image src="/static/img/zuanshi.png" mode="aspectFit" /><text>{{ gift.priceDiamonds }}</text></view>
								<text class="present-charm">魅力 +{{ gift.charmValue }}</text>
							</view>
						</view>
					</view>
				</scroll-view>
				<view class="gift-pay-button present-pay-button" :class="{ disabled: presentLoading || presentSending || !selectedPresent }" @click="handleSendPresent">
					<text>{{ presentSending ? '赠送中...' : '赠送' }}</text>
					<view v-if="!presentSending && selectedPresent" class="present-pay-price"><image src="/static/img/zuanshi.png" mode="aspectFit" /><text>{{ selectedPresent.priceDiamonds }}</text></view>
				</view>
			</view>
		</view>

		<SvgaGiftPlayer :visible="presentAnimationVisible" :animation-url="playingPresent.animationUrl || ''" :static-image-url="playingPresent.staticImageUrl || ''" @close="handlePresentAnimationClose" />
		<view v-if="flashViewerVisible" class="flash-viewer" @touchmove.stop.prevent @click.stop>
			<image v-if="flashViewerPath" class="flash-viewer-image" :src="flashViewerPath" mode="aspectFit" />
			<view v-else class="flash-viewer-loading"><view class="loading-dot" /></view>
			<view class="flash-viewer-close" @click="closeFlashViewer">×</view>
			<view class="flash-viewer-countdown">{{ flashViewerRemaining }}</view>
		</view>
	</view>
</template>

<script>
import { DEFAULT_AVATAR_URL } from '../../config';
import { closeFlashImage, ensurePrivateConversation, fetchConversationMessages, markConversationRead, openFlashImage, sendConversationMessage } from '../../api/message';
import { refreshMessageTabBadge } from '../../utils/messageTabBadge';
import { createMembershipOrder, fetchMembership, fetchMembershipOrder } from '../../api/membership';
import { getCurrentUser } from '../../utils/auth';
import { showRequestError } from '../../utils/feedback';
import { uploadAudio, uploadFlashImage, uploadImage } from '../../utils/request';
import { listOutboxMessages, removeOutboxMessage, saveOutboxMessage } from '../../utils/chatOutbox';
import { isChatUserOnline, sendChatSocketEvent, subscribeChatEvents } from '../../utils/chatSocket';
import * as profileGuard from '../../utils/profileGuard';
import VipName from '../../components/VipName.vue';
import SvgaGiftPlayer from '../../components/SvgaGiftPlayer.vue';
import { fetchGifts, sendGift as sendPresent } from '../../api/gift';
import { fetchDiamonds } from '../../api/diamond';
import { isGiftEffectHandled, markGiftEffectHandled, removeGiftEffect, takeGiftEffects } from '../../utils/giftEffectQueue';
import {
	loadPrivateMessageSubscriptionStatus,
	requestPrivateMessageSubscription
} from '../../utils/privateMessageSubscription';

const PAGE_SIZE = 50;
const TIME_GAP = 5 * 60 * 1000;
const MAX_AUDIO_DURATION = 60;
const MIN_AUDIO_DURATION = 1;
const RECORD_CANCEL_DISTANCE_PX = 50;
const MESSAGE_STATUS_RANK = { sent: 1, delivered: 2, read: 3 };
const SUBSCRIPTION_AUTO_PROMPT_STORAGE_KEY = 'private_message_subscription_auto_prompt_date';
const SYSTEM_EMOJIS = [
	'😀', '😂', '😊', '😍', '😘', '😎', '🥳', '🤔',
	'🤭', '🥺', '😭', '😤', '😡', '😱', '😴', '🤢',
	'👍', '👎', '👌', '✌️', '🤞', '👏', '🙌', '🙏',
	'💪', '👀', '💋', '❤️', '💔', '💯', '✨', '🔥',
	'🎉', '🎁', '🌹', '☀️', '🌙', '⭐', '🍀', '☕'
];

export default {
	components: { SvgaGiftPlayer, VipName },
	data() {
		return {
			conversationId: '',
			conversation: null,
			loading: false,
			loadingOlder: false,
			refreshing: false,
			mediaBusy: false,
			subscriptionRequesting: false,
			subscriptionStatusLoaded: false,
			subscriptionAutoRequestedThisVisit: false,
			subscriptionStatus: {
				supported: true,
				availableCount: 0
			},
			sendQueue: Promise.resolve(),
			profileReady: false,
			vipPromptVisible: false,
			giftPromptVisible: false,
			giftPlansLoading: false,
			giftPaying: false,
			giftPlans: [],
			selectedGiftPlanType: 'quarterly',
			selectedGiftPlan: null,
			presentPanelVisible: false,
			presentLoading: false,
			presentSending: false,
			presents: [],
			selectedPresent: null,
			playingPresent: {},
			presentAnimationVisible: false,
			pendingPresentEffects: [],
			presentDiamondBalance: 0,
			presentIsMember: false,
			flashViewerVisible: false,
			flashViewerPath: '',
			flashViewerMessageId: '',
			flashViewerExpiresAt: '',
			flashViewerRemaining: 0,
			flashViewerTimer: null,
			flashOpeningMessageId: '',
			flashCaptureHandler: null,
			hasMore: true,
			initialized: false,
			statusBarHeight: 44,
			headerTopPadding: 44,
			headerInnerHeight: 52,
			headerRightPadding: 24,
			headerHeight: 116,
			scrollViewportHeight: 600,
			keyboardHeight: 0,
			keyboardResetTimer: null,
			nearBottom: true,
			pendingNewCount: 0,
			typingTimer: null,
			typingActive: false,
			peerTypingTimer: null,
			realtimeUnsubscribe: null,
			peer: {
				id: '',
				name: '想法来客',
				avatar: DEFAULT_AVATAR_URL,
				gender: '',
				age: 0,
				city: '',
				state: '未知城市',
				match: false,
				online: false,
				isMember: false
			},
			myAvatar: DEFAULT_AVATAR_URL,
			draft: '',
			scrollIntoView: 'chat-bottom',
			showToolPanel: false,
			showEmojiPanel: false,
			voiceMode: false,
			voiceToggleBlockedUntil: 0,
			recording: false,
			recordingStopPending: false,
			recordingCanceled: false,
			recordingGestureActive: false,
			recordingCancelPending: false,
			recordingTouchStartY: 0,
			recordingStartAt: 0,
			recordingDuration: 0,
			recordingTimer: null,
			recorderManager: null,
			recorderStopHandler: null,
			recorderErrorHandler: null,
			audioPlayer: null,
			playingAudioId: '',
			audioPlaybackStarted: false,
			quickReplies: ['我也这么想', '展开说说', '这个好有共鸣', '等我慢慢回你'],
			emojis: SYSTEM_EMOJIS,
			tools: [
				{ label: '图片', icon: '/static/img/tupian.png', iconClass: 'image', action: 'image' },
				{ label: '闪图', icon: '/static/img/shantu.png', iconClass: 'flash', action: 'flashImage' },
				{ label: '礼物', icon: '/static/img/liwu.png', iconClass: 'gift', action: 'gift' },
				{ label: '赠送会员', icon: '/static/img/VIP-icon.png', iconClass: 'vip', action: 'membershipGift' }
			],
			messages: []
		};
	},
	computed: {
		subscriptionBannerVisible() {
			return this.subscriptionStatusLoaded
				&& this.subscriptionStatus.supported
				&& this.subscriptionStatus.availableCount <= 0;
		},
		chatScrollStyle() {
			return {
				paddingTop: this.subscriptionBannerVisible
					? `calc(${this.headerHeight}px + 100rpx)`
					: `${this.headerHeight}px`
			};
		},
		composerStyle() {
			if (!this.keyboardHeight) return '';
			return `bottom: ${this.keyboardHeight}px;`;
		},
		quickRepliesStyle() {
			if (!this.keyboardHeight) return '';
			return `bottom: calc(96rpx + ${this.keyboardHeight}px);`;
		},
		newMessagePillStyle() {
			if (!this.keyboardHeight) return '';
			return `bottom: calc(222rpx + ${this.keyboardHeight}px);`;
		},
		toolPanelStyle() {
			if (!this.keyboardHeight) return '';
