			return `calc(226rpx + ${this.keyboardHeight}px)`;
		},
		systemPrompt() {
			if (!this.conversation) return '';
			const sourceType = this.conversation.sourceType || '';
			if (sourceType === 'drift_letter') return '你们因一封信开始聊天';
			if (sourceType === 'recommend') return '你们因「同频推荐」开始聊天';
			if (sourceType === 'greet') return '你们因一次打招呼开始聊天';
			return '';
		},
		timelineItems() {
			const items = [];
			let previousTime = 0;

			if (this.systemPrompt) {
				items.push({ key: 'system-source', kind: 'system', label: this.systemPrompt });
			}

			this.messages.forEach((message) => {
				const time = this.getMessageTime(message);
				if (!previousTime || (time && time - previousTime > TIME_GAP)) {
					items.push({
						key: `time-${message.id}`,
						kind: 'time',
						label: this.formatTimeTip(message.createdAt)
					});
				}

				if (message.messageType === 'membership_gift') {
					items.push({
						key: `gift-${message.id}`,
						kind: 'membership-gift',
						label: message.mine
							? `你向 ${this.peer.name} ${message.content}`
							: `${this.peer.name}向你${message.content}`
					});
				} else if (message.messageType === 'gift' && message.gift) {
					items.push({ key: `present-${message.id}`, kind: 'gift', message });
				} else {
					items.push({ key: `message-${message.id}`, kind: 'message', message });
				}
				if (time) previousTime = time;
			});

			return items;
		}
