				this.subscriptionStatus = {
					supported: Boolean(status && status.supported),
					availableCount: Number((status && status.availableCount) || 0)
				};
				this.subscriptionStatusLoaded = true;
			} catch (error) {}
		},
		getSubscriptionPromptDateKey() {
			const date = new Date();
			return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
		},
		getSubscriptionPromptStorageKey() {
			const userId = String((getCurrentUser() || {}).id || 'anonymous');
			return `${SUBSCRIPTION_AUTO_PROMPT_STORAGE_KEY}:${userId}`;
		},
		hasAutoPromptedSubscriptionToday() {
			try {
				return uni.getStorageSync(this.getSubscriptionPromptStorageKey()) === this.getSubscriptionPromptDateKey();
			} catch (error) {
