				const result = await requestPrivateMessageSubscription();
				if (!result.accepted) {
					if (!fromSend) this.showToast('未开启私信提醒');
					return;
				}
				const status = result.status || {};
				this.subscriptionStatus = {
					supported: status.supported !== false,
					availableCount: Number(status.availableCount || 0)
				};
				this.showToast('已开启下一次私信提醒');
			} catch (error) {
