		},
		mapPeer(peer = {}) {
			return {
				id: peer.id || '',
				name: peer.nickname || peer.stampNo || '想法来客',
				avatar: peer.avatarUrl || DEFAULT_AVATAR_URL,
				gender: peer.gender || '',
				age: Number(peer.age || 0),
				city: peer.city || '',
				state: peer.city || '未知城市',
				match: false,
				online: Boolean(this.peer && this.peer.id === peer.id && this.peer.online),
				isMember: Boolean(peer.isMember)
			};
		},
		mapMessage(item = {}) {
			const mine = Boolean(item.mine);
			const pending = Boolean(item.pending);
			const failed = Boolean(item.failed);
			let gift = null;
			if (item.messageType === 'gift') {
				try {
					gift = typeof item.content === 'string' ? JSON.parse(item.content) : item.content;
				} catch (error) {
					gift = null;
				}
			}
			return {
				id: item.id,
				mine,
				content: item.content || '',
				messageType: item.messageType || 'text',
				imageUrl: item.imageUrl || '',
				audioUrl: item.audioUrl || '',
				audioDuration: Number(item.audioDuration || 0),
				status: this.getMessageStatus({ mine, pending, failed, status: item.status }),
				rawStatus: item.status || 'sent',
				clientMessageId: item.clientMessageId || '',
				deliveredAt: item.deliveredAt || null,
				readAt: item.readAt || null,
				flashOpenedAt: item.flashOpenedAt || '',
				flashViewed: Boolean(item.flashViewed || item.flashOpenedAt),
				flashUploadId: item.flashUploadId || '',
				pending,
				failed,
				createdAt: item.createdAt || new Date().toISOString(),
				localOnly: Boolean(item.localOnly),
				gift
			};
		},
		getMessageStatus(message = {}) {
			if (!message.mine) return '';
			if (message.pending) return '发送中';
			if (message.failed) return '发送失败，点此重试';
			if (message.status === 'read') return '已读';
			if (message.status === 'delivered') return '已送达';
			if (message.status === 'sent') return '已发送';
			return message.status || '已发送';
		},
		applyConversation(conversation = {}) {
			if (!conversation || !conversation.id) return;
			this.conversation = conversation;
			this.conversationId = conversation.id;
			if (conversation.peer) {
				this.peer = this.mapPeer(conversation.peer);
				this.peer.online = isChatUserOnline(this.peer.id);
				this.updatePeerState();
			}
		},
		updatePeerState() {
			if (this.peer.typing) {
				this.peer.state = '正在输入...';
				return;
			}
			this.peer.state = this.peer.city || '未知城市';
		},
		async initConversation(options = {}) {
			this.applyCurrentUser();
			const id = options.id || '';
			const to = options.to || '';
			if (!id && !to) {
				uni.showToast({ title: '缺少会话信息', icon: 'none' });
				return;
			}

			this.loading = true;
			try {
				if (to) {
					const conversation = await ensurePrivateConversation(to);
					this.applyConversation(conversation);
				} else {
					this.conversationId = id;
				}

				await this.refreshMessages({ replace: true, stickToBottom: true });
				this.restoreOutbox();
				this.initialized = true;
				this.startRealtime();
				this.consumePendingPresentEffects();
			} catch (error) {
				showRequestError(error, '会话加载失败');
			} finally {
				this.loading = false;
			}
		},
		async refreshMessages(options = {}) {
			if (!this.conversationId || this.refreshing) return;
			this.refreshing = true;
			try {
				const result = await fetchConversationMessages(this.conversationId, { limit: PAGE_SIZE });
				const unreadCount = Number((result.conversation && result.conversation.unreadCount) || 0);
				this.applyConversation(result.conversation);
				const incoming = (Array.isArray(result.messages) ? result.messages : []).map(this.mapMessage);
				this.enqueueUnreadPresentEffects(incoming, unreadCount);
				const hadMessages = this.messages.length;
				this.mergeMessages(incoming, { replace: Boolean(options.replace) });
				if (options.replace) {
					this.hasMore = incoming.length >= PAGE_SIZE;
				}

				if (result.conversation && result.conversation.id && (options.stickToBottom || this.nearBottom)) {
					this.markReadSilently();
				}

				if (options.stickToBottom || !hadMessages || this.nearBottom) {
					this.scrollToBottom();
				}
			} catch (error) {
				if (!options.silent) showRequestError(error, '消息加载失败');
			} finally {
				this.refreshing = false;
			}
		},
		async loadOlderMessages() {
			if (!this.conversationId || this.loadingOlder || !this.hasMore || !this.messages.length) return;
			const firstRemoteMessage = this.messages.find((item) => !item.localOnly);
			if (!firstRemoteMessage) return;

			this.loadingOlder = true;
			const anchorId = firstRemoteMessage.id;
			try {
				const result = await fetchConversationMessages(this.conversationId, {
					before: firstRemoteMessage.createdAt,
					beforeId: firstRemoteMessage.id,
					limit: PAGE_SIZE
				});
				this.applyConversation(result.conversation);
				const incoming = (Array.isArray(result.messages) ? result.messages : []).map(this.mapMessage);
				this.hasMore = incoming.length >= PAGE_SIZE;
				this.mergeMessages(incoming);
				this.scrollToMessage(anchorId);
			} catch (error) {
				showRequestError(error, '历史消息加载失败');
			} finally {
				this.loadingOlder = false;
			}
		},
		mergeMessages(incoming = [], options = {}) {
			const source = options.replace
				? this.messages.filter((item) => item.localOnly || item.pending || item.failed)
				: this.messages;
			const map = new Map();

			[...source, ...incoming].forEach((message) => {
				if (!message || !message.id) return;
				const existing = map.get(message.id) || {};
				const merged = { ...existing, ...message };
				const existingStatus = existing.rawStatus || '';
				const incomingStatus = message.rawStatus || '';
				if ((MESSAGE_STATUS_RANK[existingStatus] || 0) > (MESSAGE_STATUS_RANK[incomingStatus] || 0)) {
					merged.rawStatus = existingStatus;
					merged.deliveredAt = existing.deliveredAt || merged.deliveredAt;
					merged.readAt = existing.readAt || merged.readAt;
					merged.status = this.getMessageStatus({ ...merged, status: existingStatus });
				}
				map.set(message.id, merged);
			});

			this.messages = Array.from(map.values()).sort((a, b) => {
				const timeDiff = this.getMessageTime(a) - this.getMessageTime(b);
				return timeDiff || String(a.id).localeCompare(String(b.id));
			});
		},
		setHeaderHeight() {
			try {
				const info = uni.getSystemInfoSync();
				const rpxToPx = (info.windowWidth || 375) / 750;
				this.statusBarHeight = info.statusBarHeight || 44;

				if (uni.getMenuButtonBoundingClientRect) {
					const menuButton = uni.getMenuButtonBoundingClientRect();
					if (menuButton && menuButton.top && menuButton.height) {
						const sideGap = Math.max(76, (info.windowWidth || 375) - menuButton.left + 8);
						const bottomGap = Math.round(12 * rpxToPx);
						this.headerTopPadding = menuButton.top;
						this.headerInnerHeight = menuButton.height;
						this.headerRightPadding = sideGap;
						this.headerHeight = menuButton.top + menuButton.height + bottomGap;
						this.scrollViewportHeight = Math.max(240, (info.windowHeight || 667) - this.headerHeight - Math.round(120 * rpxToPx));
						return;
					}
				}

				this.headerTopPadding = this.statusBarHeight + Math.round(10 * rpxToPx);
				this.headerInnerHeight = Math.round(64 * rpxToPx);
				this.headerRightPadding = Math.round(76 * rpxToPx);
				this.headerHeight = this.headerTopPadding + this.headerInnerHeight + Math.round(12 * rpxToPx);
				this.scrollViewportHeight = Math.max(240, (info.windowHeight || 667) - this.headerHeight - Math.round(120 * rpxToPx));
			} catch (error) {
				this.headerTopPadding = 44;
				this.headerInnerHeight = 52;
				this.headerRightPadding = 76;
				this.headerHeight = 116;
				this.scrollViewportHeight = 600;
			}
		},
		sendFromComposer() {
			const content = String(this.draft || '').trim();
			if (!content) return;
			this.blockVoiceToggle();
			this.requestReplyReminderOnSend();
			this.send();
		},
		handleSendTouchStart() {
			this.blockVoiceToggle();
		},
		blockVoiceToggle() {
			this.voiceToggleBlockedUntil = Date.now() + 500;
		},
		async send(contentOverride = '', options = {}) {
			const override = typeof contentOverride === 'string' ? contentOverride : '';
			const content = String(override || this.draft || '').trim();
			if (!content) return;
			if (!this.conversationId) {
				uni.showToast({ title: '会话还没有准备好', icon: 'none' });
				return;
			}
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '私信' }))) return;

			const localId = this.createLocalMessageId();
			const localMessage = this.mapMessage({
				id: localId,
				mine: true,
				content,
				pending: true,
				localOnly: true,
				createdAt: new Date().toISOString()
			});

			if (!options.preserveDraft) this.draft = '';
			this.stopTyping();
			if (!options.keepPanels) this.closePanels();
			this.mergeMessages([localMessage]);
			this.scrollToBottom();

			const payload = { content };
			this.persistOutbox(localMessage, payload);
			this.enqueueMessageSend(localId, payload, '发送失败');
		},
		useQuickReply(text) {
			this.send(text);
		},
		async retryMessage(message) {
			if (!message || !message.failed || message.retrying) return;
			const localId = message.id;
			this.updateLocalMessage(localId, { pending: true, failed: false, retrying: true, status: '发送中' });

			this.enqueueMessageSend(
				localId,
				() => this.buildRetryMessagePayload(localId, message),
				'重试失败'
			);
		},
		replaceLocalMessage(localId, realMessage) {
			this.messages = this.messages.filter((item) => item.id !== localId);
			this.mergeMessages([realMessage]);
		},
		updateLocalMessage(id, updates) {
			this.messages = this.messages.map((item) => {
				if (item.id !== id) return item;
				const next = { ...item, ...updates };
				return { ...next, status: this.getMessageStatus(next) };
			});
		},
		markLocalMessageFailed(id) {
			this.updateLocalMessage(id, {
				pending: false,
				failed: true,
				retrying: false,
				localOnly: true,
				status: '发送失败，点此重试'
			});
		},
		createLocalMessageId() {
			return `local_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
		},
		buildMessagePayload(message = {}) {
			if (message.messageType === 'flash_image') {
				return { messageType: 'flash_image', flashUploadId: message.flashUploadId || '' };
			}
			if (message.messageType === 'image') {
				return {
					messageType: 'image',
					imageUrl: message.imageUrl
				};
			}

			if (message.messageType === 'audio') {
				return {
					messageType: 'audio',
					audioUrl: message.audioUrl,
					audioDuration: Number(message.audioDuration || 0)
				};
			}

			return {
				messageType: 'text',
				content: message.content || ''
			};
		},
		isRemoteImageUrl(value = '') {
			return /^(https?:)?\/\//i.test(String(value || '')) || String(value || '').startsWith('/uploads/');
		},
		async buildRetryMessagePayload(localId, message = {}) {
			if (message.messageType === 'flash_image') {
				if (message.flashUploadId) return this.buildMessagePayload(message);
				const uploaded = await uploadFlashImage(message.imageUrl);
				const flashUploadId = uploaded && uploaded.uploadId ? uploaded.uploadId : '';
				if (!flashUploadId) throw new Error('闪图上传失败。');
				this.updateLocalMessage(localId, { flashUploadId });
				return { messageType: 'flash_image', flashUploadId };
			}
			if (message.messageType === 'audio') {
				if (this.isRemoteImageUrl(message.audioUrl)) {
					return this.buildMessagePayload(message);
				}

				const uploaded = await uploadAudio(message.audioUrl);
				const audioUrl = uploaded && uploaded.url ? uploaded.url : '';
				if (!audioUrl) {
					throw new Error('语音上传失败。');
				}

				this.updateLocalMessage(localId, { audioUrl });
				return {
					messageType: 'audio',
					audioUrl,
					audioDuration: Number(message.audioDuration || 0)
				};
			}

			if (message.messageType !== 'image') {
				return this.buildMessagePayload(message);
			}

			if (this.isRemoteImageUrl(message.imageUrl)) {
				return this.buildMessagePayload(message);
			}

			const uploaded = await uploadImage(message.imageUrl);
			const imageUrl = uploaded && uploaded.url ? uploaded.url : '';
			if (!imageUrl) {
				throw new Error('图片上传失败。');
			}

			this.updateLocalMessage(localId, { imageUrl });
			return {
				messageType: 'image',
				imageUrl
			};
		},
		async chooseAndSendImage() {
			if (this.mediaBusy) return;
			if (!this.conversationId) {
				uni.showToast({ title: '会话还没有准备好', icon: 'none' });
				return;
			}
			if (!this.profileReady) {
				if (!(await profileGuard.ensureProfileCompleted({ actionText: '私信' }))) return;
				this.profileReady = true;
			}

			this.closePanels();

			let chosenPath = '';
			try {
				const result = await uni.chooseImage({
					count: 1,
					sizeType: ['compressed', 'original'],
					sourceType: ['album', 'camera']
				});
				chosenPath = result && result.tempFilePaths && result.tempFilePaths[0] ? result.tempFilePaths[0] : '';
			} catch (error) {
				const errorMessage = String((error && (error.errMsg || error.message)) || '');
				if (!/cancel/i.test(errorMessage)) {
					showRequestError(error, '选择图片失败');
				}
				return;
			}

			if (!chosenPath) return;
			this.mediaBusy = true;
			try {
				let uploadPath = chosenPath;
				try {
					const compressed = await uni.compressImage({
						src: chosenPath,
						quality: 76,
						compressedWidth: 1280
					});
					uploadPath = compressed.tempFilePath || chosenPath;
				} catch (error) {}

				const localId = this.createLocalMessageId();
				const localMessage = this.mapMessage({
					id: localId,
					mine: true,
					messageType: 'image',
					imageUrl: uploadPath,
					pending: true,
					localOnly: true,
					createdAt: new Date().toISOString()
				});

				this.mergeMessages([localMessage]);
				this.scrollToBottom();

				this.enqueueMessageSend(localId, async () => {
					const uploaded = await uploadImage(uploadPath);
					const imageUrl = uploaded && uploaded.url ? uploaded.url : '';
					if (!imageUrl) throw new Error('图片上传失败。');
					this.updateLocalMessage(localId, { imageUrl });
					return { messageType: 'image', imageUrl };
				}, '图片发送失败');
			} finally {
				this.mediaBusy = false;
			}
		},
		async chooseAndSendFlashImage() {
			if (this.mediaBusy) return;
			if (!this.conversationId) return this.showToast('会话还没有准备好');
			if (!this.profileReady) {
				if (!(await profileGuard.ensureProfileCompleted({ actionText: '私信' }))) return;
				this.profileReady = true;
			}
			this.closePanels();
			let chosenPath = '';
			try {
				const result = await uni.chooseImage({ count: 1, sizeType: ['compressed', 'original'], sourceType: ['album', 'camera'] });
				chosenPath = result && result.tempFilePaths && result.tempFilePaths[0] ? result.tempFilePaths[0] : '';
			} catch (error) {
				if (!/cancel/i.test(String((error && (error.errMsg || error.message)) || ''))) showRequestError(error, '选择闪图失败');
				return;
			}
			if (!chosenPath) return;
			this.mediaBusy = true;
			try {
				let uploadPath = chosenPath;
				try {
					const compressed = await uni.compressImage({ src: chosenPath, quality: 76, compressedWidth: 1280 });
					uploadPath = compressed.tempFilePath || chosenPath;
				} catch (error) {}

				const localId = this.createLocalMessageId();
				const localMessage = this.mapMessage({
					id: localId,
					mine: true,
					messageType: 'flash_image',
					imageUrl: uploadPath,
					pending: true,
					localOnly: true,
					createdAt: new Date().toISOString()
				});
				this.mergeMessages([localMessage]);
				this.scrollToBottom();
				this.enqueueMessageSend(localId, async () => {
					const uploaded = await uploadFlashImage(uploadPath);
					const flashUploadId = uploaded && uploaded.uploadId ? uploaded.uploadId : '';
					if (!flashUploadId) throw new Error('闪图上传失败。');
					this.updateLocalMessage(localId, { flashUploadId });
					return { messageType: 'flash_image', flashUploadId };
				}, '闪图发送失败');
			} finally {
				this.mediaBusy = false;
			}
		},
		enqueueMessageSend(localId, payload, fallbackMessage) {
			const task = async () => {
				try {
