				return;
			}

			const rawDuration = Number(result.duration || (Date.now() - this.recordingStartAt));
			const duration = Math.round(rawDuration / 1000);
			const tempFilePath = result.tempFilePath || '';
			this.clearRecordingTimer();

			if (!tempFilePath) {
				uni.showToast({ title: '没有录到声音', icon: 'none' });
				return;
			}

			if (rawDuration < MIN_AUDIO_DURATION * 1000) {
				uni.showToast({ title: '说得太轻啦，再多说一点', icon: 'none' });
