					this.updateLocalMessage(data.messageId, { flashOpenedAt: data.openedAt || new Date().toISOString(), flashViewed: true });
				}
				return;
			}
			if (event.type === 'gift.sent') {
				const data = event.data || {};
				if (data.conversationId === this.conversationId) {
					this.presentPanelVisible = false;
					this.refreshMessages({ silent: true, stickToBottom: this.nearBottom });
					if (data.recipientUserId === (getCurrentUser() || {}).id && data.gift) {
						removeGiftEffect(data);
						this.enqueuePresentEffect(data.gift, data.transactionId || (data.message && data.message.id));
						if (Number(data.giftBonusDiamonds || 0) > 0) {
							this.showToast(`礼物彩蛋：+${Number(data.giftBonusDiamonds)} 钻石`);
						}
					}
				}
				return;
			}
			if (event.type === 'membership.gifted') {
				const data = event.data || {};
				if (data.conversationId === this.conversationId) {
					this.giftPromptVisible = false;
					this.refreshMessages({ silent: true, stickToBottom: this.nearBottom });
				}
				return;
			}
			if (event.type === 'ready') {
				if (this.peer.id) {
					this.peer.online = isChatUserOnline(this.peer.id);
					this.updatePeerState();
				}
				sendChatSocketEvent('presence.subscribe');
				this.refreshMessages({ silent: true, stickToBottom: this.nearBottom });
				return;
			}
			if (event.type === 'presence.snapshot') {
				this.peer.online = isChatUserOnline(this.peer.id);
				this.updatePeerState();
				return;
			}
			if (event.type === 'presence.changed' && event.data && event.data.userId === this.peer.id) {
