				if (!this.peer.online) this.clearPeerTyping();
				this.updatePeerState();
				return;
			}
			if (event.type === 'typing.changed') {
				const data = event.data || {};
				if (data.conversationId === this.conversationId && data.userId === this.peer.id) {
					this.peer.typing = Boolean(data.typing);
