			if (!filePath) return;
			try {
				if (typeof wx !== 'undefined' && typeof wx.getFileSystemManager === 'function') {
					wx.getFileSystemManager().unlink({ filePath, fail: () => {} });
				}
			} catch (error) {}
		},
		async openFlashMessage(message = {}) {
			if (!message.id || message.mine || this.flashOpeningMessageId || this.flashViewerVisible) return;
			if (message.flashOpenedAt) return this.showToast('这张闪图已经查看过了');
			this.flashOpeningMessageId = message.id;
			try {
				const result = await openFlashImage(this.conversationId, message.id);
				this.updateLocalMessage(message.id, { flashOpenedAt: result.openedAt, flashViewed: true });
				this.flashViewerVisible = true;
				this.flashViewerMessageId = message.id;
				this.flashViewerExpiresAt = result.expiresAt;
				this.flashViewerPath = '';
				this.setFlashCaptureProtection(true);
				this.startFlashViewerTimer();
				let path = '';
				for (let attempt = 0; attempt < 2 && !path; attempt += 1) {
					try { path = await this.downloadFlashMedia(result.mediaUrl); } catch (error) { if (attempt) throw error; }
				}
				if (this.flashViewerMessageId === message.id && this.flashViewerVisible) {
					this.flashViewerPath = path;
				} else {
					this.removeFlashTempFile(path);
				}
			} catch (error) {
				this.closeFlashViewer({ silent: true });
				showRequestError(error, '闪图打开失败');
			} finally {
				this.flashOpeningMessageId = '';
			}
		},
		startFlashViewerTimer() {
			if (this.flashViewerTimer) clearInterval(this.flashViewerTimer);
			const update = () => {
				const remaining = Math.max(0, Math.ceil((new Date(this.flashViewerExpiresAt).getTime() - Date.now()) / 1000));
				this.flashViewerRemaining = remaining;
				if (!remaining) this.closeFlashViewer({ silent: true });
			};
			update();
			if (this.flashViewerVisible) this.flashViewerTimer = setInterval(update, 200);
		},
		closeFlashViewer(options = {}) {
			const messageId = this.flashViewerMessageId;
			const filePath = this.flashViewerPath;
			if (this.flashViewerTimer) clearInterval(this.flashViewerTimer);
			this.flashViewerTimer = null;
			this.flashViewerVisible = false;
			this.flashViewerPath = '';
			this.flashViewerMessageId = '';
			this.flashViewerExpiresAt = '';
			this.flashViewerRemaining = 0;
			this.setFlashCaptureProtection(false);
			this.removeFlashTempFile(filePath);
			if (messageId) closeFlashImage(this.conversationId, messageId).catch(() => {});
		},
		toggleEmojiPanel() {
			this.showToolPanel = false;
			this.showEmojiPanel = !this.showEmojiPanel;
			if (this.showEmojiPanel) {
				this.dismissKeyboard();
				this.scrollToBottom();
			}
		},
		sendEmoji(emoji) {
			if (!emoji) return;
			this.send(emoji, { preserveDraft: true, keepPanels: true });
		},
		closePanels() {
			this.showToolPanel = false;
			this.showEmojiPanel = false;
		},
		handlePageTap() {
			this.closePanels();
			this.dismissKeyboard();
		},
		scrollToBottom() {
			this.nearBottom = true;
			this.$nextTick(() => {
				this.scrollIntoView = '';
				setTimeout(() => {
					this.scrollIntoView = 'chat-bottom';
				}, 40);
			});
		},
		scrollToMessage(id) {
			if (!id) return;
			this.$nextTick(() => {
				this.scrollIntoView = '';
				setTimeout(() => {
					this.scrollIntoView = `msg-${id}`;
				}, 40);
			});
		},
		getMessageTime(message = {}) {
			const time = new Date(message.createdAt || 0).getTime();
			return Number.isFinite(time) ? time : 0;
		},
		formatTimeTip(value) {
			const date = new Date(value || '');
			if (!date.getTime()) return '';
			const now = new Date();
			const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
			const targetDay = new Date(date.getFullYear(), date.getMonth(), date.getDate());
			const dayDiff = Math.round((today - targetDay) / (24 * 60 * 60 * 1000));
			const time = `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;

			if (dayDiff === 0) return `今天 ${time}`;
			if (dayDiff === 1) return `昨天 ${time}`;
			if (date.getFullYear() === now.getFullYear()) return `${date.getMonth() + 1}月${date.getDate()}日 ${time}`;
			return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日 ${time}`;
		},
		async goUserHome() {
			if (!this.peer.id) return;
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '查看主页' }))) return;
			uni.navigateTo({ url: `/pages/user/index?id=${this.peer.id}` });
		},
		showMoreActions() {
			uni.showActionSheet({
				itemList: ['举报', '拉黑', '清空聊天记录'],
				itemColor: '#d4688a',
				success: (result) => {
					const labels = ['举报', '拉黑', '清空聊天记录'];
					this.showToast(`${labels[result.tapIndex]}暂未开放`);
				}
			});
		},
		async handleToolClick(item) {
			if (item.action === 'image') {
				try {
					await this.chooseAndSendImage();
				} catch (error) {
					showRequestError(error, '选择图片失败');
				}
				return;
			}
			if (item.action === 'flashImage') {
				await this.chooseAndSendFlashImage();
				return;
			}
			if (item.action === 'membershipGift') {
				await this.openGiftPrompt();
				return;
			}
			if (item.action === 'gift') {
				await this.openPresentPanel();
				return;
			}

			this.showToast(item.tip || `${item.label}暂未开放`);
		},
		async openPresentPanel() {
			if (!this.peer.id || !this.conversationId) return this.showToast('会话还没有准备好');
			this.closePanels();
			this.selectedPresent = null;
			this.presentPanelVisible = true;
			this.presentLoading = true;
			try {
				const [giftResult, diamonds] = await Promise.all([fetchGifts(), fetchDiamonds()]);
				this.presents = Array.isArray(giftResult && giftResult.items) ? giftResult.items : [];
				this.presentIsMember = Boolean(giftResult && giftResult.isMember);
				this.presentDiamondBalance = Number((diamonds && diamonds.balance) || 0);
				this.selectedPresent = this.presents.find((gift) => this.presentIsMember || !gift.memberOnly) || null;
			} catch (error) {
				this.presentPanelVisible = false;
				showRequestError(error, '礼物加载失败');
			} finally {
				this.presentLoading = false;
			}
		},
		async refreshPresentDiamondBalance() {
			try {
				const diamonds = await fetchDiamonds();
				this.presentDiamondBalance = Number((diamonds && diamonds.balance) || 0);
			} catch (error) {}
		},
		closePresentPanel() {
			if (!this.presentSending) this.presentPanelVisible = false;
		},
		selectPresent(gift) {
			if (gift.memberOnly && !this.presentIsMember) {
				uni.showModal({ title: 'VIP 专属礼物', content: '开通 VIP 后即可赠送该礼物。', confirmText: '去开通', confirmColor: '#d4688a', success: ({ confirm }) => { if (confirm) uni.navigateTo({ url: '/pages/membership/index' }); } });
				return;
			}
			this.selectedPresent = gift;
		},
		playPresent(gift = {}) {
			if (!gift.staticImageUrl && !gift.animationUrl) return;
			this.playingPresent = gift;
			this.presentAnimationVisible = true;
		},
		enqueuePresentEffect(gift = {}, effectId = '') {
			if (!gift.staticImageUrl && !gift.animationUrl) return;
			const id = String(effectId || '').trim();
			if (id && isGiftEffectHandled(id)) return;
			if (id && this.pendingPresentEffects.some((item) => item.id === id)) return;
			if (id) markGiftEffectHandled(id);
			this.pendingPresentEffects.push({ id, gift });
			this.playNextPresentEffect();
		},
		enqueueUnreadPresentEffects(messages = [], unreadCount = 0) {
			if (!unreadCount) return;
			messages
				.filter((message) => !message.mine)
				.slice(-unreadCount)
				.filter((message) => message.messageType === 'gift' && message.gift)
				.forEach((message) => {
					this.enqueuePresentEffect(message.gift, message.gift.transactionId || message.id);
				});
		},
		playNextPresentEffect() {
			if (this.presentAnimationVisible || !this.pendingPresentEffects.length) return;
			const next = this.pendingPresentEffects.shift();
			this.playPresent(next.gift);
		},
		handlePresentAnimationClose() {
			this.presentAnimationVisible = false;
			this.$nextTick(() => this.playNextPresentEffect());
		},
		consumePendingPresentEffects() {
			const currentUserId = (getCurrentUser() || {}).id;
			takeGiftEffects(this.conversationId, currentUserId).forEach((item) => {
				this.enqueuePresentEffect(item.gift, item.id);
			});
		},
		handleSendPresent() {
			const gift = this.selectedPresent;
			if (!gift || this.presentLoading || this.presentSending) return;
			if (Number(gift.priceDiamonds || 0) > this.presentDiamondBalance) {
				this.promptDiamondRecharge('赠送这份礼物');
				return;
			}
			this.sendSelectedPresent(gift);
		},
		async sendSelectedPresent(gift) {
			this.presentSending = true;
			try {
				const result = await sendPresent(this.conversationId, { giftId: gift.id, clientTransactionId: this.createLocalMessageId() });
				this.presentDiamondBalance = Math.max(0, this.presentDiamondBalance - Number(gift.priceDiamonds || 0));
				this.presentPanelVisible = false;
				this.playPresent((result && result.gift) || gift);
				await this.refreshMessages({ silent: true, stickToBottom: true });
			} catch (error) {
				if (this.isDiamondInsufficient(error)) {
					this.promptDiamondRecharge('赠送这份礼物');
					return;
				}
				showRequestError(error, '礼物赠送失败');
			} finally {
				this.presentSending = false;
			}
		},
		promptDiamondRecharge(actionText = '继续操作') {
			uni.showModal({
				title: '钻石不足',
				content: `当前钻石不足，充值后即可${actionText}。`,
				confirmText: '去充值',
				confirmColor: '#d4688a',
				success: ({ confirm }) => {
					if (confirm) uni.navigateTo({ url: '/pages/diamonds/index?recharge=1' });
				}
			});
		},
		async openGiftPrompt() {
			if (!this.peer.id || !this.conversationId) {
				this.showToast('会话还没有准备好');
				return;
			}
			this.closePanels();
			this.giftPromptVisible = true;
			if (this.giftPlans.length || this.giftPlansLoading) return;
			this.giftPlansLoading = true;
			try {
				const summary = await fetchMembership();
				this.giftPlans = Array.isArray(summary && summary.plans) ? summary.plans : [];
				const preferredPlan = this.giftPlans.find((plan) => plan.type === this.selectedGiftPlanType)
					|| this.giftPlans[0]
					|| null;
				this.selectGiftPlan(preferredPlan);
			} catch (error) {
				this.giftPromptVisible = false;
				showRequestError(error, '会员套餐加载失败');
			} finally {
				this.giftPlansLoading = false;
			}
		},
		closeGiftPrompt() {
			if (this.giftPaying) return;
			this.giftPromptVisible = false;
		},
		formatGiftPrice(value) {
			return Number(value || 0).toFixed(2);
		},
		selectGiftPlan(plan) {
			if (!plan || !plan.type) {
				this.selectedGiftPlan = null;
				return;
			}
			this.selectedGiftPlanType = plan.type;
			this.selectedGiftPlan = plan;
		},
		confirmGiftMembership() {
			if (!this.selectedGiftPlan || this.giftPaying) return;
			const plan = this.selectedGiftPlan;
			uni.showModal({
				title: '确认赠送',
				content: `将向 ${this.peer.name} 赠送${plan.name}（${plan.days}天），需支付 ¥${this.formatGiftPrice(plan.price)}。`,
				confirmText: '确认支付',
				confirmColor: '#d4688a',
				success: (result) => {
					if (result.confirm) this.payGiftMembership(plan);
				}
			});
		},
		async payGiftMembership(plan) {
			if (this.giftPaying) return;
			this.giftPaying = true;
			try {
				const order = await createMembershipOrder(plan.type, {
					recipientUserId: this.peer.id,
					conversationId: this.conversationId
				});
				if (!order || !order.payment) throw new Error('支付参数未返回，请稍后再试。');
				if (!uni.requestPayment) throw new Error('当前环境不支持微信支付，请使用微信小程序真机。');
				await new Promise((resolve, reject) => {
					uni.requestPayment({ ...order.payment, success: resolve, fail: reject });
				});
				const paid = await this.waitForGiftOrderPaid(order.orderId);
				this.giftPromptVisible = false;
				if (paid) {
					uni.showToast({ title: '会员已赠送', icon: 'success' });
					this.refreshMessages({ silent: true, stickToBottom: true });
				} else {
					uni.showModal({
						title: '到账确认中',
						content: '支付已完成，会员将在微信支付回调确认后自动到账，请勿重复支付。',
						showCancel: false,
						confirmText: '我知道了',
						confirmColor: '#d4688a'
					});
				}
			} catch (error) {
				const errorMessage = String((error && (error.errMsg || error.message)) || '');
				if (!/cancel/i.test(errorMessage)) showRequestError(error, '会员赠送失败');
			} finally {
				this.giftPaying = false;
			}
		},
		async waitForGiftOrderPaid(orderId) {
			for (let attempt = 0; attempt < 8; attempt += 1) {
				if (attempt) await new Promise((resolve) => setTimeout(resolve, 800));
				try {
					const order = await fetchMembershipOrder(orderId);
					if (order && order.status === 'paid') return true;
					if (order && order.status === 'failed') return false;
				} catch (error) {
					if (attempt === 7) return false;
				}
			}
			return false;
		},
		showToast(title) {
			uni.showToast({ title, icon: 'none' });
		},
		goBack() {
			const pages = getCurrentPages();
			if (pages.length > 1) {
				uni.navigateBack();
			} else {
				uni.switchTab({ url: '/pages/messages/index' });
			}
		}
	}
};
</script>

