.system-tip {
	display: inline-flex;
	max-width: 560rpx;
	min-height: 42rpx;
	margin-top: 6rpx;
	padding: 0 20rpx;
	border-radius: 999rpx;
	background: rgba(255, 255, 255, 0.7);
	border: 1rpx solid rgba(232, 234, 242, 0.88);
}

.chat-loading,
.chat-empty {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	min-height: 520rpx;
	text-align: center;
}

.chat-loading {
	gap: 18rpx;
	color: #9da2b1;
	font-size: 24rpx;
}

.loading-dot {
	width: 34rpx;
	height: 34rpx;
	border-radius: 50%;
	border: 4rpx solid rgba(143, 123, 255, 0.2);
	border-top-color: #8f7bff;
	animation: loadingSpin 0.8s linear infinite;
}

@keyframes loadingSpin {
	from { transform: rotate(0deg); }
	to { transform: rotate(360deg); }
}

.chat-empty {
	padding: 40rpx 28rpx;
	color: #8d92a1;
}

.empty-avatar {
	width: 116rpx;
	height: 116rpx;
	border-radius: 50%;
	background: #eef0f5;
	box-shadow: 0 12rpx 30rpx rgba(54, 58, 80, 0.08);
}

.empty-title {
	margin-top: 22rpx;
	max-width: 520rpx;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	color: #333743;
	font-size: 28rpx;
	font-weight: 400;
}

.empty-desc {
	margin-top: 12rpx;
	color: #9fa4b3;
	font-size: 23rpx;
	font-weight: 400;
}

.message-row {
	display: flex;
	align-items: flex-start;
	gap: 14rpx;
	margin-top: 26rpx;
}

.message-row.mine {
	flex-direction: row-reverse;
}

.message-row.sending {
	opacity: 0.82;
}

.avatar {
	width: 64rpx;
	height: 64rpx;
	border-radius: 50%;
	background: #eef0f5;
	flex-shrink: 0;
}

.bubble-wrap {
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	max-width: 538rpx;
}

.message-row.mine .bubble-wrap {
	align-items: flex-end;
}

.message-tag,
.message-status {
	font-size: 19rpx;
	font-weight: 400;
	color: #a0a4b1;
}

.message-tag {
	margin: 0 0 8rpx 10rpx;
}

.message-status {
	margin-top: 8rpx;
	padding-right: 10rpx;
}

.message-status.failed {
	color: #ef5f6f;
}

.message-status.sending {
	color: #a7a9b5;
}

.bubble {
	position: relative;
	max-width: 538rpx;
	padding: 20rpx 24rpx;
	border-radius: 24rpx;
	background: #ffffff;
	color: #30333d;
	font-size: 27rpx;
	font-weight: 400;
	line-height: 1.58;
	box-shadow: 0 4rpx 16rpx rgba(45, 49, 70, 0.035);
	word-break: break-word;
	overflow-wrap: anywhere;
}

.membership-gift-message {
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 10rpx;
	width: fit-content;
	max-width: 580rpx;
	min-height: 52rpx;
	margin: 8rpx auto;
	padding: 8rpx 18rpx;
	border: 1rpx solid rgba(212, 104, 138, 0.18);
	border-radius: 8rpx;
	background: rgba(255, 246, 249, 0.96);
	box-sizing: border-box;
	color: #a84f6b;
	font-size: 22rpx;
	line-height: 1.45;
	text-align: center;
}

.membership-gift-message image {
	width: 30rpx;
	height: 30rpx;
	flex-shrink: 0;
}

.bubble.image-bubble {
	width: 300rpx;
	height: 300rpx;
	padding: 0;
	overflow: hidden;
	background: #ffffff;
}

.bubble.audio-bubble {
	min-width: 176rpx;
	max-width: 370rpx;
	padding: 17rpx 22rpx;
	transition: background 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}

.audio-message {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 18rpx;
	height: 40rpx;
	width: 100%;
}

.message-row.mine .audio-message {
	flex-direction: row-reverse;
}

.audio-signal {
	position: relative;
	width: 50rpx;
	height: 40rpx;
	color: #7a6570;
	flex-shrink: 0;
}

.message-row:not(.mine) .audio-signal {
	color: #747986;
}

.message-row.mine .audio-signal {
	transform: scaleX(-1);
}

.audio-signal-dot {
	position: absolute;
	left: 3rpx;
	top: 50%;
	width: 9rpx;
	height: 9rpx;
	border-radius: 50%;
	background: currentColor;
	transform: translateY(-50%);
}

.audio-signal-wave {
	position: absolute;
	top: 50%;
	border-right: 4rpx solid currentColor;
	border-radius: 0 100% 100% 0;
	box-sizing: border-box;
	transform: translateY(-50%);
}

.audio-signal-wave.wave-one {
	left: 10rpx;
	width: 10rpx;
	height: 18rpx;
	opacity: 0.5;
}

.audio-signal-wave.wave-two {
	left: 14rpx;
	width: 18rpx;
	height: 29rpx;
	opacity: 0.68;
	border-right-width: 4rpx;
	border-radius: 0 90% 90% 0;
}

.audio-signal-wave.wave-three {
	left: 18rpx;
	width: 27rpx;
	height: 40rpx;
	opacity: 0.85;
	border-right-width: 4rpx;
	border-radius: 0 85% 85% 0;
}

.audio-duration {
	flex-shrink: 0;
	min-width: 38rpx;
	color: #76616c;
	font-size: 23rpx;
	font-weight: 500;
	line-height: 40rpx;
	text-align: right;
	opacity: 0.82;
}

.message-row:not(.mine) .audio-duration {
	color: #6d7280;
	text-align: left;
}

.bubble.audio-bubble.loading {
	opacity: 0.76;
}

.bubble.audio-bubble.loading .audio-signal-dot {
	animation: audioLoadingPulse 0.8s ease-in-out infinite;
}

.message-row.mine .bubble.audio-bubble.playing {
	background: #f5cddd;
	box-shadow: 0 8rpx 22rpx rgba(190, 81, 120, 0.16);
	transform: translateY(-1rpx);
}

.message-row:not(.mine) .bubble.audio-bubble.playing {
	background: #f2f3f7;
	box-shadow: 0 8rpx 22rpx rgba(60, 66, 84, 0.1);
	transform: translateY(-1rpx);
}

.bubble.audio-bubble.playing .audio-signal-dot,
.bubble.audio-bubble.playing .audio-signal-wave {
	animation: audioSignalPulse 1.05s ease-in-out infinite;
}

.bubble.audio-bubble.playing .wave-one {
	animation-delay: 0s;
}

.bubble.audio-bubble.playing .wave-two {
	animation-delay: 0.13s;
}

.bubble.audio-bubble.playing .wave-three {
	animation-delay: 0.26s;
}

@keyframes audioSignalPulse {
	0%, 100% { opacity: 0.22; }
	45%, 65% { opacity: 1; }
}

@keyframes audioLoadingPulse {
	0%, 100% { opacity: 0.35; transform: translateY(-50%) scale(0.78); }
	50% { opacity: 0.9; transform: translateY(-50%) scale(1); }
}

.message-image {
	display: block;
	width: 300rpx;
	height: 300rpx;
	background: #edf0f6;
}

.bubble::before {
	content: '';
	position: absolute;
	left: -8rpx;
	top: 22rpx;
	width: 18rpx;
	height: 18rpx;
	background: inherit;
	border-radius: 4rpx;
	transform: rotate(45deg);
}

.message-row.mine .bubble {
	background: #f8dce8;
	color: #4a3540;
	box-shadow: 0 6rpx 18rpx rgba(212, 104, 138, 0.11);
}

.message-row.failed .bubble {
	background: #fff1f3;
	color: #5a3038;
	box-shadow: 0 6rpx 18rpx rgba(239, 95, 111, 0.09);
}

.message-row.mine .bubble::before {
	left: auto;
	right: -8rpx;
}

.quick-replies {
	position: fixed;
	left: 0;
	right: 0;
	bottom: calc(96rpx + env(safe-area-inset-bottom));
	z-index: 28;
	display: flex;
	gap: 12rpx;
	padding: 12rpx 24rpx 10rpx;
	overflow-x: auto;
	white-space: nowrap;
	background: linear-gradient(180deg, rgba(247, 248, 252, 0), rgba(247, 248, 252, 0.96) 35%, rgba(247, 248, 252, 0.98));
	box-sizing: border-box;
}

.quick-reply {
	flex-shrink: 0;
	height: 54rpx;
	padding: 0 20rpx;
	border-radius: 999rpx;
	background: rgba(255, 255, 255, 0.78);
	border: 1rpx solid #e7eaf3;
	color: #737887;
	font-size: 22rpx;
	font-weight: 400;
	line-height: 54rpx;
}

.bottom-spacer {
	height: calc(226rpx + env(safe-area-inset-bottom));
}

.composer {
	position: fixed;
	left: 0;
	right: 0;
	bottom: 0;
	z-index: 30;
	display: flex;
	align-items: center;
	gap: 12rpx;
	padding: 14rpx 24rpx;
	padding-bottom: calc(14rpx + env(safe-area-inset-bottom));
	background: rgba(255, 255, 255, 0.98);
	border-top: 1rpx solid #e9ebf3;
	backdrop-filter: blur(18rpx);
}

.keyboard-open .composer {
	padding-bottom: 14rpx;
}

.tool-btn,
.emoji-btn,
.voice-btn,
.send-btn {
	display: flex;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;
}

.tool-btn,
.emoji-btn,
.voice-btn {
	position: relative;
	width: 60rpx;
	height: 60rpx;
	border-radius: 50%;
	background: #f4f5fa;
	color: #687080;
}

.bubble.flash-bubble {
	width: 304rpx;
	min-height: 122rpx;
	padding: 14rpx;
	border: 1rpx solid #dcece6;
	border-radius: 22rpx;
	background: #f5fbf8;
	color: #27463d;
	box-sizing: border-box;
	box-shadow: 0 8rpx 22rpx rgba(45, 105, 83, 0.08);
}

.message-row.mine .bubble.flash-bubble {
	border-color: #efd8e1;
	background: #fff3f7;
	color: #583b47;
	box-shadow: 0 8rpx 22rpx rgba(183, 85, 119, 0.09);
}

.flash-message {
	display: flex;
	align-items: center;
	gap: 16rpx;
	width: 100%;
	min-width: 0;
}

.flash-message-icon {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 82rpx;
	height: 82rpx;
	border: 1rpx solid #d6eee4;
	border-radius: 18rpx;
	background: #ffffff;
	box-shadow: 0 4rpx 12rpx rgba(42, 104, 81, 0.06);
	flex-shrink: 0;
}

.message-row.mine .flash-message-icon {
	border-color: #f0d9e2;
	box-shadow: 0 4rpx 12rpx rgba(171, 79, 111, 0.06);
}

.flash-message-icon image {
	display: block;
	width: 54rpx;
	height: 54rpx;
}

.flash-message-copy,
.flash-message-title,
.flash-message-state {
	display: block;
}

.flash-message-copy {
	flex: 1;
	min-width: 0;
}

.flash-message-head,
.flash-message-status {
	display: flex;
	align-items: center;
}

.flash-message-head {
	gap: 10rpx;
	height: 36rpx;
}

.flash-message-title {
	font-size: 27rpx;
	font-weight: 700;
	line-height: 36rpx;
}

.flash-message-badge {
	display: block;
	height: 28rpx;
	padding: 0 9rpx;
	border-radius: 8rpx;
	background: #dff3ea;
	color: #328363;
	font-size: 18rpx;
	font-weight: 600;
	line-height: 28rpx;
}

.message-row.mine .flash-message-badge {
	background: #f5dfe8;
	color: #ae5875;
}

.flash-message-status {
	height: 32rpx;
	margin-top: 7rpx;
	gap: 8rpx;
}

.flash-message-dot {
	width: 9rpx;
	height: 9rpx;
	border-radius: 50%;
	background: #3fa87e;
	box-shadow: 0 0 0 5rpx rgba(63, 168, 126, 0.1);
	flex-shrink: 0;
}

.message-row.mine .flash-message-dot {
	background: #d4688a;
	box-shadow: 0 0 0 5rpx rgba(212, 104, 138, 0.1);
}

.flash-message-state {
	min-width: 0;
	color: #648078;
	font-size: 21rpx;
	line-height: 32rpx;
	white-space: nowrap;
}

.message-row.mine .flash-message-state {
	color: #98707f;
}

.flash-message-arrow {
	display: block;
	margin-left: auto;
	color: #3d9875;
	font-size: 32rpx;
	font-weight: 400;
	line-height: 28rpx;
}

.flash-message.viewed {
	opacity: 0.58;
}

.flash-message.viewed .flash-message-dot {
	background: #a6ada9;
	box-shadow: none;
}

.emoji-btn {
	overflow: hidden;
}

.emoji-icon {
	display: block;
	width: 42rpx;
	height: 42rpx;
}

.emoji-btn.active {
	background: rgba(212, 104, 138, 0.12);
	color: #d4688a;
}

.tool-btn::before,
.tool-btn::after {
	content: '';
	position: absolute;
	background: currentColor;
	border-radius: 999rpx;
}

.tool-btn::before {
	width: 28rpx;
	height: 4rpx;
}

.tool-btn::after {
	width: 4rpx;
	height: 28rpx;
}

.voice-icon {
	display: block;
	width: 42rpx;
	height: 42rpx;
}

.new-message-pill {
	position: fixed;
	right: 28rpx;
	bottom: calc(222rpx + env(safe-area-inset-bottom));
	z-index: 24;
	height: 56rpx;
	padding: 0 24rpx;
	border: 1rpx solid #e4e1f8;
	border-radius: 999rpx;
	background: rgba(255, 255, 255, 0.96);
	box-shadow: 0 8rpx 24rpx rgba(80, 70, 130, 0.12);
	color: #7564cf;
	font-size: 22rpx;
	line-height: 56rpx;
}

.voice-btn.active {
	background: rgba(212, 104, 138, 0.12);
}

.input {
	flex: 1;
	height: 66rpx;
	min-width: 0;
	padding: 0 24rpx;
	border-radius: 999rpx;
	background: #f1f2f7;
	color: #343743;
	font-size: 26rpx;
	font-weight: 400;
}

.voice-record-btn {
	display: flex;
	align-items: center;
	justify-content: center;
	flex: 1;
	height: 66rpx;
	min-width: 0;
	border-radius: 999rpx;
	background: #f1f2f7;
	color: #5f6574;
	font-size: 25rpx;
	font-weight: 400;
	transition: background 0.16s ease, color 0.16s ease, transform 0.16s ease;
}

.voice-record-btn.recording {
	background: #fff0f6;
	color: #d4688a;
	transform: scale(0.985);
}

.voice-record-btn.recording.canceling {
	background: #ffecee;
	color: #e44f63;
}

.placeholder {
	color: #aaaebb;
}

.send-btn {
	height: 68rpx;
	min-width: 78rpx;
	padding: 0 22rpx;
	border-radius: 999rpx;
	background: #d4688a;
	color: #ffffff;
	font-size: 24rpx;
	font-weight: 400;
}

.send-btn.disabled {
	background: #dcdfe8;
	color: #ffffff;
}

.send-btn:not(.disabled):active {
	background: #bd5b7b;
}

.recording-float {
	position: fixed;
	left: 50%;
	bottom: calc(132rpx + env(safe-area-inset-bottom));
	z-index: 35;
	display: flex;
	align-items: center;
	gap: 12rpx;
	min-height: 58rpx;
	padding: 0 24rpx;
	border-radius: 999rpx;
	background: rgba(255, 255, 255, 0.96);
	border: 1rpx solid rgba(248, 210, 226, 0.9);
	box-shadow: 0 12rpx 36rpx rgba(212, 104, 138, 0.14);
	color: #d4688a;
	font-size: 22rpx;
	transform: translateX(-50%);
	backdrop-filter: blur(16rpx);
}

.recording-float.canceling {
	border-color: rgba(228, 79, 99, 0.3);
	background: rgba(255, 240, 242, 0.98);
	box-shadow: 0 12rpx 36rpx rgba(228, 79, 99, 0.18);
	color: #e44f63;
}

.recording-float.canceling .recording-pulse {
	background: #e44f63;
	box-shadow: none;
	animation: none;
}

.recording-pulse {
	width: 16rpx;
	height: 16rpx;
	border-radius: 50%;
	background: #d4688a;
	box-shadow: 0 0 0 0 rgba(212, 104, 138, 0.32);
	animation: recordingPulse 1.2s ease-out infinite;
}

.vip-prompt-mask {
	position: fixed;
	inset: 0;
	z-index: 100;
	display: flex;
	align-items: center;
	justify-content: center;
	padding: 36rpx;
	background: rgba(23, 22, 28, 0.48);
	backdrop-filter: blur(5rpx);
}

.vip-prompt {
	display: flex;
	flex-direction: column;
	align-items: center;
	width: 100%;
	max-width: 590rpx;
	padding: 46rpx 34rpx 30rpx;
	border: 1rpx solid rgba(212, 104, 138, 0.16);
	border-radius: 24rpx;
	background: #ffffff;
	box-shadow: 0 30rpx 80rpx rgba(32, 25, 29, 0.22);
}

.vip-mark {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 94rpx;
	height: 52rpx;
	border-radius: 8rpx;
	background: #d4688a;
	color: #ffffff;
	font-size: 25rpx;
	font-weight: 600;
	line-height: 1;
}

.vip-prompt-title {
	display: block;
	margin-top: 24rpx;
	color: #2f2930;
	font-size: 34rpx;
	font-weight: 600;
	line-height: 1.25;
	text-align: center;
}

.vip-prompt-desc {
	display: block;
	margin-top: 16rpx;
	color: #817780;
	font-size: 25rpx;
	line-height: 1.65;
	text-align: center;
}

.vip-prompt-actions {
	display: grid;
	grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
	gap: 18rpx;
	width: 100%;
	margin-top: 34rpx;
}

.vip-prompt-btn {
	display: flex;
	align-items: center;
	justify-content: center;
	height: 76rpx;
	border-radius: 12rpx;
	font-size: 26rpx;
	font-weight: 500;
}

.vip-prompt-btn.secondary {
	border: 1rpx solid #e6e1e5;
	background: #f7f5f7;
	color: #746d74;
}

.vip-prompt-btn.primary {
	background: #d4688a;
	color: #ffffff;
	box-shadow: 0 10rpx 24rpx rgba(212, 104, 138, 0.24);
}

.vip-prompt-btn.primary:active {
	background: #bd5b7b;
}

.gift-prompt-mask {
	position: fixed;
	inset: 0;
	z-index: 110;
	display: flex;
	align-items: flex-end;
	justify-content: center;
	background: rgba(23, 22, 28, 0.48);
}

.gift-prompt {
	width: 100%;
	padding: 30rpx 28rpx calc(28rpx + env(safe-area-inset-bottom));
	border-radius: 20rpx 20rpx 0 0;
	background: #ffffff;
	box-shadow: 0 -20rpx 60rpx rgba(35, 25, 29, 0.16);
	box-sizing: border-box;
}

.gift-prompt-head {
	display: flex;
	align-items: center;
	min-height: 72rpx;
}

.gift-prompt-head > image {
	width: 58rpx;
	height: 58rpx;
	margin-right: 16rpx;
	flex-shrink: 0;
}

.gift-prompt-copy {
	display: flex;
	flex: 1;
	min-width: 0;
	flex-direction: column;
}

.gift-prompt-title {
	color: #30272d;
	font-size: 32rpx;
	font-weight: 600;
	line-height: 1.3;
}

.gift-prompt-target {
	margin-top: 5rpx;
	overflow: hidden;
	color: #91858d;
	font-size: 22rpx;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.gift-close {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 60rpx;
	height: 60rpx;
	color: #928990;
	font-size: 46rpx;
	font-weight: 300;
	line-height: 1;
}

.gift-plans-loading {
	display: flex;
	align-items: center;
	justify-content: center;
	height: 250rpx;
	color: #9a9097;
	font-size: 24rpx;
}

.gift-plan-list {
	display: grid;
	grid-template-columns: repeat(3, minmax(0, 1fr));
	gap: 14rpx;
	margin-top: 28rpx;
}

.gift-plan {
	position: relative;
	display: flex;
	min-width: 0;
	min-height: 184rpx;
	padding: 24rpx 12rpx 18rpx;
	border: 2rpx solid #ece7ea;
	border-radius: 8rpx;
	background: #faf9fa;
	box-sizing: border-box;
	flex-direction: column;
	align-items: center;
}

.gift-plan.selected {
	border-color: #d4688a;
	background: #fff6f9;
	box-shadow: 0 8rpx 20rpx rgba(212, 104, 138, 0.12);
}

.gift-plan-main {
	display: flex;
	min-width: 0;
	flex-direction: column;
	align-items: center;
}

.gift-plan-name {
	color: #3d343a;
	font-size: 26rpx;
	font-weight: 600;
}

.gift-plan-days {
	margin-top: 8rpx;
	color: #9a9097;
	font-size: 19rpx;
	text-align: center;
}

.gift-plan-price {
	margin-top: auto;
	color: #d4688a;
	font-size: 30rpx;
	font-weight: 600;
}

.gift-plan-check {
	position: absolute;
	right: 8rpx;
	top: 8rpx;
	width: 22rpx;
	height: 22rpx;
